        add_action('admin_post_ezevo_test_integration',[self::class,'test_integration']);add_action('admin_post_ezevo_activate_provider',[self::class,'activate_provider']);
        add_action('admin_post_ezevo_run_sync',[self::class,'run_sync']);add_action('admin_post_ezevo_seed_demo',[self::class,'seed_demo']);add_action('admin_notices',[self::class,'notices']);
    }
    public static function menu(): void {
        $cap='ezev_view_operations'; if(!current_user_can($cap)&&current_user_can('manage_options'))$cap='manage_options';
        add_menu_page('EZEV Operations','EZEV Operations',$cap,'ezev-operations',[self::class,'dashboard'],'dashicons-chart-area',4);
        add_submenu_page('ezev-operations','Dashboard','Dashboard',$cap,'ezev-operations',[self::class,'dashboard']);
        add_submenu_page('ezev-operations','Stations','Station Operations',$cap,'ezevo-stations',[self::class,'stations']);
        add_submenu_page('ezev-operations','Chargers','Chargers',$cap,'ezevo-chargers',[self::class,'chargers']);
        add_submenu_page('ezev-operations','Energy','Energy',$cap,'ezevo-energy',[self::class,'energy']);
        add_submenu_page('ezev-operations','Sessions','Sessions',$cap,'ezevo-sessions',[self::class,'sessions']);
        add_submenu_page('ezev-operations','Alerts','Alerts',$cap,'ezevo-alerts',[self::class,'alerts']);
        add_submenu_page('ezev-operations','Maintenance','Maintenance',$cap,'ezevo-maintenance',[self::class,'maintenance']);
        add_submenu_page('ezev-operations','Manual Data','Manual Data',$cap,'ezevo-manual',[self::class,'manual_data']);
        add_submenu_page('ezev-operations','Integrations','Integrations','manage_options','ezevo-integrations',[self::class,'integrations']);
        add_submenu_page('ezev-operations','Sync Logs','Sync Logs','manage_options','ezevo-logs',[self::class,'logs']);
    }
    public static function assets(string $hook): void {
        if(strpos($hook,'ezev')===false)return;
        wp_enqueue_style('ezevo-inter','https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap',[],null);
        wp_enqueue_style('ezevo-admin',EZEVO_URL.'assets/css/admin.css',['ezevo-inter'],EZEVO_VERSION);
        wp_enqueue_script('ezevo-admin',EZEVO_URL.'assets/js/admin.js',[],EZEVO_VERSION,true);
        $stations=[];
        if(class_exists('EZEV_Core_Stations')){
            $stations=EZEV_Core_Stations::list();
            global $wpdb;
            $rows=$wpdb->get_results("SELECT station_id,SUM(status='available') available,SUM(status='charging') charging,SUM(status='faulted') faulted,SUM(current_power_kw) power FROM ".EZEV_Operations_DB::table('chargers')." GROUP BY station_id",ARRAY_A)?:[];
            $state=[];foreach($rows as $r){$state[$r['station_id']]=$r;}
            foreach($stations as &$st){$o=$state[$st['station_id']]??[];$st['ops_available']=(int)($o['available']??0);$st['ops_charging']=(int)($o['charging']??0);$st['ops_faulted']=(int)($o['faulted']??0);$st['ops_power']=(float)($o['power']??0);$st['ops_status']=$st['ops_faulted']>0?'faulted':($st['ops_charging']>0?'charging':'available');}unset($st);
        }
        $gkey='';$mapid='DEMO_MAP_ID';
        if(class_exists('EZEV_Core_Admin')){$gkey=EZEV_Core_Admin::decrypt_secret((string)get_option('ezev_map_api_key',''));$mapid=(string)get_option('ezev_google_map_id','DEMO_MAP_ID');}
        wp_localize_script('ezevo-admin','EZEVO_ADMIN',['brand'=>['dark'=>'#123D38','green'=>'#2FA866','lime'=>'#B7D52A','blue'=>'#2E7892'],'googleMapsKey'=>$gkey,'googleMapId'=>$mapid,'stations'=>$stations,'coreMapSettings'=>admin_url('admin.php?page=ezev-map-settings')]);
    }

    private static function header(string $title, string $subtitle = ''): void {
        $provider = EZEV_Operations_Provider_Manager::active(); ?>
        <div class="ezevo-wrap">
            <div class="ezevo-hero">
                <div class="ezevo-brand">
                    <img src="<?php echo esc_url(EZEVO_URL . 'assets/images/ezev-logo.svg'); ?>" alt="EZEV">
                    <span>OPERATIONS</span>
                </div>
                <div>
                    <h1><?php echo esc_html($title); ?></h1>
                    <?php if ($subtitle): ?><p><?php echo esc_html($subtitle); ?></p><?php endif; ?>
                </div>
                <div class="ezevo-provider">
                    <i></i>
                    <span><?php echo esc_html($provider->label()); ?></span>
                    <small><?php echo esc_html(strtoupper($provider->mode())); ?> DATA</small>
                </div>
            </div>
    <?php }

    private static function footer(): void {
        echo '</div>';
    }

    private static function station_name(string $station_id): string {
        if (class_exists('EZEV_Core_Stations')) {
            $post_id = EZEV_Core_Stations::find_by_station_id($station_id);
            if ($post_id) {
                return (string) get_the_title($post_id);
            }
        }
        return $station_id;
    }

