        <div class="ezevo-grid-2"><section class="ezevo-panel"><div class="ezevo-panel-head"><div><span class="ezevo-eyebrow">ENERGY TREND</span><h2>Last 7 days</h2></div><a href="<?php echo esc_url(admin_url('admin.php?page=ezevo-energy')); ?>">View energy</a></div><div class="ezevo-chart" data-ezevo-bars='<?php echo esc_attr(wp_json_encode($days)); ?>'></div></section><section class="ezevo-panel"><div class="ezevo-panel-head"><div><span class="ezevo-eyebrow">CURRENT STATUS</span><h2>Charger mix</h2></div><span class="ezevo-badge manual"><?php echo esc_html(strtoupper(EZEV_Operations_Provider_Manager::active()->mode())); ?></span></div><div class="ezevo-status-ring" data-total="<?php echo (int)$o['chargers_total']; ?>" data-available="<?php echo (int)$o['chargers_available']; ?>" data-charging="<?php echo (int)$o['chargers_charging']; ?>" data-faulted="<?php echo (int)$o['chargers_faulted']; ?>"><div><strong><?php echo (int)$o['chargers_total']; ?></strong><span>chargers</span></div></div><div class="ezevo-legend"><span><i class="avail"></i>Available <?php echo (int)$o['chargers_available']; ?></span><span><i class="charge"></i>Charging <?php echo (int)$o['chargers_charging']; ?></span><span><i class="fault"></i>Faulted <?php echo (int)$o['chargers_faulted']; ?></span></div></section></div>
        <div class="ezevo-grid-2"><section class="ezevo-panel"><div class="ezevo-panel-head"><div><span class="ezevo-eyebrow">ALERTS</span><h2>Requires attention</h2></div><a href="<?php echo esc_url(admin_url('admin.php?page=ezevo-alerts')); ?>">All alerts</a></div><?php if(!$alerts):?><div class="ezevo-empty">No open alerts.</div><?php else:?><div class="ezevo-alert-list"><?php foreach($alerts as $a):?><div class="ezevo-alert <?php echo esc_attr($a['severity']); ?>"><span></span><div><strong><?php echo esc_html($a['title']); ?></strong><small><?php echo esc_html(self::station_name($a['station_id']).' · '.$a['charger_id']); ?></small></div><b><?php echo esc_html(strtoupper($a['severity'])); ?></b></div><?php endforeach;?></div><?php endif;?></section><section class="ezevo-panel"><span class="ezevo-eyebrow">PROVIDER ARCHITECTURE</span><h2>Manual now → API later</h2><div class="ezevo-provider-flow"><div>Manual / Demo Provider</div><b>→</b><div>EZEV Operations</div><b>→</b><div>Dashboard + Portals</div></div><div class="ezevo-callout">When EVD/Juhang API arrives, add endpoint + credentials in Integrations, test connection, map fields and activate the provider. Frontend code does not need to change.</div><div class="ezevo-actions"><a class="ezevo-button primary" href="<?php echo esc_url(admin_url('admin.php?page=ezevo-integrations')); ?>">Configure integrations</a><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('ezevo_run_sync');?><input type="hidden" name="action" value="ezevo_run_sync"><button class="ezevo-button">Run sync now</button></form></div></section></div>
