    private static function kpi(string $label,string|int|float $value,string $hint,string $icon): void {?><div class="ezevo-kpi"><span class="dashicons dashicons-<?php echo esc_attr($icon); ?>"></span><div><small><?php echo esc_html($label); ?></small><strong><?php echo esc_html((string)$value); ?></strong><p><?php echo esc_html($hint); ?></p></div></div><?php }
    public static function stations(): void { global $wpdb;$rows=$wpdb->get_results("SELECT station_id,COUNT(*) chargers,SUM(status='available') available,SUM(status='charging') charging,SUM(status='faulted') faulted,SUM(current_power_kw) current_power,MAX(updated_at) updated_at FROM ".EZEV_Operations_DB::table('chargers')." GROUP BY station_id ORDER BY station_id",ARRAY_A)?:[];self::header('Station Operations','Operational state aggregated by station ID.');?> <section class="ezevo-panel"><div class="ezevo-table-scroll"><table class="ezevo-table"><thead><tr><th>Station</th><th>Chargers</th><th>Available</th><th>Charging</th><th>Faulted</th><th>Current Power</th><th>Updated</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?php echo esc_html(self::station_name($r['station_id'])); ?></strong><small><?php echo esc_html($r['station_id']); ?></small></td><td><?php echo (int)$r['chargers']; ?></td><td><span class="ezevo-pill available"><?php echo (int)$r['available']; ?></span></td><td><span class="ezevo-pill charging"><?php echo (int)$r['charging']; ?></span></td><td><span class="ezevo-pill faulted"><?php echo (int)$r['faulted']; ?></span></td><td><?php echo esc_html(number_format((float)$r['current_power'],1)); ?> kW</td><td><?php echo esc_html($r['updated_at']); ?></td></tr><?php endforeach;?></tbody></table></div></section><?php self::footer(); }
    public static function chargers(): void { global $wpdb;$rows=$wpdb->get_results("SELECT * FROM ".EZEV_Operations_DB::table('chargers')." ORDER BY station_id,charger_id LIMIT 500",ARRAY_A)?:[];self::header('Chargers','Each physical charger/EVSE is linked to one Station ID.');?> <section class="ezevo-panel"><div class="ezevo-table-scroll"><table class="ezevo-table"><thead><tr><th>Charger</th><th>Station</th><th>Connector</th><th>Max Power</th><th>Status</th><th>Current Power</th><th>Last Seen</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?php echo esc_html($r['charger_id']); ?></strong><small><?php echo esc_html($r['serial_number']); ?></small></td><td><?php echo esc_html(self::station_name($r['station_id'])); ?></td><td><?php echo esc_html($r['connector_type']); ?></td><td><?php echo esc_html($r['max_power_kw']); ?> kW</td><td><span class="ezevo-pill <?php echo esc_attr($r['status']); ?>"><?php echo esc_html($r['status']); ?></span></td><td><?php echo esc_html($r['current_power_kw']); ?> kW</td><td><?php echo esc_html($r['last_seen']); ?></td></tr><?php endforeach;?></tbody></table></div></section><?php self::footer(); }
    public static function energy(): void { global $wpdb;$days=$wpdb->get_results("SELECT DATE(recorded_at) d,SUM(ev_kwh) ev,SUM(grid_kwh) grid,SUM(solar_kwh) solar,SUM(bess_charge_kwh) bc,SUM(bess_discharge_kwh) bd,MAX(peak_kw) peak FROM ".EZEV_Operations_DB::table('energy')." WHERE recorded_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 14 DAY) GROUP BY DATE(recorded_at) ORDER BY d",ARRAY_A)?:[];self::header('Energy Management','EV consumption, grid import, solar/BESS placeholders and peak demand model.');?> <div class="ezevo-grid-2"><section class="ezevo-panel"><span class="ezevo-eyebrow">ENERGY PROFILE</span><h2>14-day EV consumption</h2><div class="ezevo-chart large" data-ezevo-bars='<?php echo esc_attr(wp_json_encode(array_map(fn($x)=>['d'=>$x['d'],'v'=>$x['ev']],$days))); ?>'></div></section><section class="ezevo-panel"><span class="ezevo-eyebrow">SITE ENERGY READINESS</span><h2>Prepared for future EMS</h2><div class="ezevo-energy-flow"><div class="grid">GRID</div><b>↕</b><div class="hub">SITE BUS</div><div class="branches"><span>SOLAR</span><span>BESS</span><span>BUILDING</span><span>EVSE</span></div></div><div class="ezevo-callout">The schema already separates grid, EV, solar and BESS values. Real telemetry can replace manual/demo entries later through the provider layer.</div></section></div><section class="ezevo-panel"><div class="ezevo-table-scroll"><table class="ezevo-table"><thead><tr><th>Date</th><th>EV kWh</th><th>Grid kWh</th><th>Solar kWh</th><th>BESS Charge</th><th>BESS Discharge</th><th>Peak kW</th></tr></thead><tbody><?php foreach($days as $d):?><tr><td><?php echo esc_html($d['d']); ?></td><td><?php echo esc_html(number_format((float)$d['ev'],1)); ?></td><td><?php echo esc_html(number_format((float)$d['grid'],1)); ?></td><td><?php echo esc_html(number_format((float)$d['solar'],1)); ?></td><td><?php echo esc_html(number_format((float)$d['bc'],1)); ?></td><td><?php echo esc_html(number_format((float)$d['bd'],1)); ?></td><td><?php echo esc_html(number_format((float)$d['peak'],1)); ?></td></tr><?php endforeach;?></tbody></table></div></section><?php self::footer(); }
    public static function sessions(): void { global $wpdb;$rows=$wpdb->get_results("SELECT * FROM ".EZEV_Operations_DB::table('sessions')." ORDER BY started_at DESC LIMIT 500",ARRAY_A)?:[];self::header('Charging Sessions','Session ledger. Billing fields can be added later without changing station identity.');?> <section class="ezevo-panel"><div class="ezevo-table-scroll"><table class="ezevo-table"><thead><tr><th>Session</th><th>Station</th><th>Charger</th><th>Started</th><th>Duration</th><th>Energy</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?php echo esc_html($r['session_id']); ?></strong></td><td><?php echo esc_html(self::station_name($r['station_id'])); ?></td><td><?php echo esc_html($r['charger_id']); ?></td><td><?php echo esc_html($r['started_at']); ?></td><td><?php echo esc_html(round(((int)$r['duration_seconds'])/60)); ?> min</td><td><?php echo esc_html($r['energy_kwh']); ?> kWh</td><td><span class="ezevo-pill available"><?php echo esc_html($r['status']); ?></span></td></tr><?php endforeach;?></tbody></table></div></section><?php self::footer(); }
    public static function alerts(): void { global $wpdb;$rows=$wpdb->get_results("SELECT * FROM ".EZEV_Operations_DB::table('alerts')." ORDER BY FIELD(status,'open','acknowledged','resolved'),FIELD(severity,'critical','high','medium','low'),occurred_at DESC LIMIT 500",ARRAY_A)?:[];self::header('Alerts','Operational events that can be acknowledged, resolved or converted into maintenance work.');?> <section class="ezevo-panel"><div class="ezevo-table-scroll"><table class="ezevo-table"><thead><tr><th>Severity</th><th>Alert</th><th>Station / Charger</th><th>Status</th><th>Occurred</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><span class="ezevo-pill <?php echo esc_attr($r['severity']); ?>"><?php echo esc_html($r['severity']); ?></span></td><td><strong><?php echo esc_html($r['title']); ?></strong><small><?php echo esc_html($r['message']); ?></small></td><td><?php echo esc_html(self::station_name($r['station_id']).' · '.$r['charger_id']); ?></td><td><?php echo esc_html($r['status']); ?></td><td><?php echo esc_html($r['occurred_at']); ?></td><td><?php if($r['status']!=='resolved'):?><form class="ezevo-inline" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('ezevo_alert_action');?><input type="hidden" name="action" value="ezevo_alert_action"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><?php if($r['status']==='open'):?><button name="do" value="ack" class="ezevo-link">Acknowledge</button><?php endif;?><button name="do" value="resolve" class="ezevo-link">Resolve</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php self::footer(); }
    public static function maintenance(): void { global $wpdb;$rows=$wpdb->get_results("SELECT m.*,u.display_name assignee FROM ".EZEV_Operations_DB::table('maintenance')." m LEFT JOIN {$wpdb->users} u ON u.ID=m.assigned_user_id ORDER BY FIELD(m.status,'open','in_progress','resolved','closed'),m.opened_at DESC LIMIT 300",ARRAY_A)?:[];self::header('Maintenance','Create work tickets and track technical resolution independently from alert ingestion.');?> <div class="ezevo-grid-2"><section class="ezevo-panel"><span class="ezevo-eyebrow">NEW TICKET</span><h2>Create maintenance work</h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('ezevo_create_ticket');?><input type="hidden" name="action" value="ezevo_create_ticket"><label>Station ID<input name="station_id" required placeholder="EZEV-PH-DEMO-001"></label><label>Charger ID<input name="charger_id" placeholder="EZEV-PH-DEMO-001-C1"></label><label>Summary<input name="summary" required placeholder="Communication lost"></label><div class="ezevo-fields-2"><label>Priority<select name="priority"><option>low</option><option selected>medium</option><option>high</option><option>critical</option></select></label><label>Assign to<select name="assigned_user_id"><option value="0">Unassigned</option><?php foreach(get_users(['role__in'=>['administrator','ezev_internal_ops','ezev_internal_technical']]) as $u):?><option value="<?php echo (int)$u->ID; ?>"><?php echo esc_html($u->display_name); ?></option><?php endforeach;?></select></label></div><label>Details<textarea name="details" rows="4"></textarea></label><button class="ezevo-button primary">Create ticket</button></form></section><section class="ezevo-panel"><span class="ezevo-eyebrow">WORKFLOW</span><h2>Alert → Ticket → Resolution</h2><div class="ezevo-workflow"><div>Alert detected</div><b>↓</b><div>Ticket created</div><b>↓</b><div>Technician assigned</div><b>↓</b><div>In progress</div><b>↓</b><div>Resolved / Closed</div></div></section></div><section class="ezevo-panel"><div class="ezevo-table-scroll"><table class="ezevo-table"><thead><tr><th>Ticket</th><th>Station</th><th>Priority</th><th>Status</th><th>Assignee</th><th>Opened</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?php echo esc_html($r['ticket_id']); ?></strong><small><?php echo esc_html($r['summary']); ?></small></td><td><?php echo esc_html(self::station_name($r['station_id'])); ?></td><td><span class="ezevo-pill <?php echo esc_attr($r['priority']); ?>"><?php echo esc_html($r['priority']); ?></span></td><td><?php echo esc_html($r['status']); ?></td><td><?php echo esc_html($r['assignee']?:'Unassigned'); ?></td><td><?php echo esc_html($r['opened_at']); ?></td></tr><?php endforeach;?></tbody></table></div></section><?php self::footer(); }

    public static function manual_data(): void {
        if(!current_user_can('ezev_view_operations')&&!current_user_can('manage_options'))wp_die('Denied');
        global $wpdb;
        $station_id=sanitize_text_field(wp_unslash($_GET['station_id']??''));
        $stations=$wpdb->get_col("SELECT DISTINCT station_id FROM ".EZEV_Operations_DB::table('chargers')." ORDER BY station_id")?:[];
        if(!$station_id && $stations)$station_id=(string)$stations[0];
        $chargers=$station_id?$wpdb->get_results($wpdb->prepare("SELECT * FROM ".EZEV_Operations_DB::table('chargers')." WHERE station_id=%s ORDER BY charger_id",$station_id),ARRAY_A):[];
        $today=$station_id?(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(ev_kwh),0) FROM ".EZEV_Operations_DB::table('energy')." WHERE station_id=%s AND DATE(recorded_at)=UTC_DATE()",$station_id)):0;
        self::header('Manual Data','Use this while no charging API exists. Every value is visibly marked manual/demo and can later be replaced by a live provider.'); ?>
        <div class="ezevo-grid-2 manual-grid"><section class="ezevo-panel"><span class="ezevo-eyebrow">SELECT STATION</span><h2>Manual operations editor</h2><form method="get" action="<?php echo esc_url(admin_url('admin.php')); ?>"><input type="hidden" name="page" value="ezevo-manual"><label>Station<select name="station_id" onchange="this.form.submit()"><?php foreach($stations as $sid):?><option value="<?php echo esc_attr($sid); ?>" <?php selected($station_id,$sid); ?>><?php echo esc_html(self::station_name($sid).' — '.$sid); ?></option><?php endforeach;?></select></label></form><?php if($station_id):?><div class="ezevo-manual-summary"><small>CURRENT MANUAL ENERGY TODAY</small><strong><?php echo esc_html(number_format($today,1)); ?> kWh</strong><span><?php echo esc_html($station_id); ?></span></div><?php endif;?></section>
        <section class="ezevo-panel"><span class="ezevo-eyebrow">DATA MODE</span><h2>Manual is temporary</h2><div class="ezevo-callout">Use this screen only before EVD/Juhang realtime integration is available. Public/partner dashboards should clearly show “Manual data” and last updated time.</div><a class="ezevo-button" href="<?php echo esc_url(admin_url('admin.php?page=ezevo-integrations')); ?>">Configure API provider</a></section></div>
        <?php if($station_id):?><section class="ezevo-panel"><div class="ezevo-panel-head"><div><span class="ezevo-eyebrow">CHARGER STATE</span><h2><?php echo esc_html(self::station_name($station_id)); ?></h2></div><span class="ezevo-badge manual">MANUAL DATA</span></div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('ezevo_save_manual');?><input type="hidden" name="action" value="ezevo_save_manual"><input type="hidden" name="station_id" value="<?php echo esc_attr($station_id); ?>"><div class="ezevo-manual-chargers"><?php foreach($chargers as $c):?><div class="ezevo-manual-card"><strong><?php echo esc_html($c['charger_id']); ?></strong><small><?php echo esc_html($c['connector_type'].' · '.$c['max_power_kw'].' kW'); ?></small><label>Status<select name="chargers[<?php echo (int)$c['id']; ?>][status]"><option value="available" <?php selected($c['status'],'available');?>>Available</option><option value="charging" <?php selected($c['status'],'charging');?>>Charging</option><option value="faulted" <?php selected($c['status'],'faulted');?>>Faulted</option><option value="offline" <?php selected($c['status'],'offline');?>>Offline</option><option value="maintenance" <?php selected($c['status'],'maintenance');?>>Maintenance</option></select></label><label>Current Power kW<input type="number" step="0.1" name="chargers[<?php echo (int)$c['id']; ?>][current_power_kw]" value="<?php echo esc_attr($c['current_power_kw']); ?>"></label></div><?php endforeach;?></div><div class="ezevo-fields-2"><label>Add EV Energy Today (kWh)<input type="number" step="0.1" min="0" name="energy_kwh" value="0"></label><label>Peak Power (kW)<input type="number" step="0.1" min="0" name="peak_kw" value="0"></label></div><button class="ezevo-button primary">Save manual operational data</button></form></section><?php endif;?>
