    public static function integrations(): void { global $wpdb;$rows=$wpdb->get_results("SELECT * FROM ".EZEV_Operations_DB::table('integrations')." ORDER BY id DESC",ARRAY_A)?:[];$edit=isset($_GET['integration'])?absint($_GET['integration']):0;$current=$edit?EZEV_Operations_Provider_Manager::integration($edit):null;$settings=$current?json_decode((string)$current['settings_json'],true):[];self::header('Integrations','Add real EVD/Juhang/OCPP gateway API credentials without modifying plugin or theme code.');?>
        <div class="ezevo-grid-2 integrations"><section class="ezevo-panel"><span class="ezevo-eyebrow">API PROVIDER</span><h2><?php echo $current?'Edit integration':'Add provider'; ?></h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('ezevo_save_integration');?><input type="hidden" name="action" value="ezevo_save_integration"><input type="hidden" name="id" value="<?php echo (int)($current['id']??0); ?>"><div class="ezevo-fields-2"><label>Provider Name<input name="name" required value="<?php echo esc_attr($current['name']??''); ?>" placeholder="Juhang Production"></label><label>Provider Type<select name="provider_type"><option value="generic_http">Generic HTTP API</option><option value="juhang">Juhang API</option><option value="evd">EVD API</option><option value="ocpp_gateway">OCPP Gateway</option></select></label></div><div class="ezevo-fields-2"><label>Environment<select name="environment"><option value="sandbox" <?php selected($current['environment']??'sandbox','sandbox');?>>Sandbox</option><option value="production" <?php selected($current['environment']??'','production');?>>Production</option></select></label><label>Authentication<select name="auth_type" data-auth-type><option value="bearer" <?php selected($current['auth_type']??'bearer','bearer');?>>Bearer Token</option><option value="api_key" <?php selected($current['auth_type']??'','api_key');?>>API Key Header</option><option value="basic" <?php selected($current['auth_type']??'','basic');?>>Basic Auth</option><option value="oauth2" <?php selected($current['auth_type']??'','oauth2');?>>OAuth 2.0 / Client</option></select></label></div><label>Base API URL<input name="base_url" value="<?php echo esc_attr($current['base_url']??''); ?>" placeholder="https://api.example.com/v1"></label><div class="ezevo-fields-2"><label>API Key / Token<input type="password" name="api_key" placeholder="<?php echo esc_attr($current?EZEV_Operations_Secrets::masked((string)$current['api_key_enc']):''); ?>"></label><label>API Secret<input type="password" name="api_secret" placeholder="<?php echo esc_attr($current?EZEV_Operations_Secrets::masked((string)$current['api_secret_enc']):''); ?>"></label></div><div class="ezevo-fields-2"><label>Client ID<input name="client_id" value="<?php echo esc_attr($current['client_id']??''); ?>"></label><label>Client Secret<input type="password" name="client_secret" placeholder="<?php echo esc_attr($current?EZEV_Operations_Secrets::masked((string)$current['client_secret_enc']):''); ?>"></label></div><label>Webhook Secret<input type="password" name="webhook_secret" placeholder="<?php echo esc_attr($current?EZEV_Operations_Secrets::masked((string)$current['webhook_secret_enc']):''); ?>"></label><span class="ezevo-eyebrow">ENDPOINTS</span><div class="ezevo-fields-2"><label>Health endpoint<input name="health_endpoint" value="<?php echo esc_attr($settings['health_endpoint']??''); ?>" placeholder="health"></label><label>Chargers endpoint<input name="chargers_endpoint" value="<?php echo esc_attr($settings['chargers_endpoint']??'chargers'); ?>"></label><label>Sessions endpoint<input name="sessions_endpoint" value="<?php echo esc_attr($settings['sessions_endpoint']??'sessions'); ?>"></label><label>Energy endpoint<input name="energy_endpoint" value="<?php echo esc_attr($settings['energy_endpoint']??'energy'); ?>"></label><label>Alerts endpoint<input name="alerts_endpoint" value="<?php echo esc_attr($settings['alerts_endpoint']??'alerts'); ?>"></label><label>Timeout seconds<input type="number" name="timeout" value="<?php echo esc_attr($settings['timeout']??15); ?>"></label></div><label>Field Mapping JSON<textarea name="mapping_json" rows="8" placeholder='{"chargers":{"charger_id":"deviceNo","station_id":"stationCode","status":"pileStatus","current_power_kw":"realPower"}}'><?php echo esc_textarea($current['mapping_json']??''); ?></textarea><small>Map EZEV canonical fields to vendor response paths. Supports dot paths.</small></label><button class="ezevo-button primary">Save integration</button></form></section>
        <section class="ezevo-panel"><span class="ezevo-eyebrow">PROVIDERS</span><h2>Connection registry</h2><div class="ezevo-integration-list"><div class="ezevo-integration-card is-active"><div><strong>Manual / Demo Provider</strong><small>Local WordPress tables</small></div><span class="ezevo-badge manual">BUILT-IN</span></div><?php foreach($rows as $r):?><div class="ezevo-integration-card <?php echo get_option('ezevo_active_provider')==='integration_'.$r['id']?'is-active':''; ?>"><div><strong><?php echo esc_html($r['name']); ?></strong><small><?php echo esc_html($r['environment'].' · '.$r['provider_type']); ?></small><em><?php echo esc_html($r['last_test_status']?strtoupper($r['last_test_status']).' · '.$r['last_test_message']:'Not tested'); ?></em></div><div class="ezevo-card-actions"><a href="<?php echo esc_url(admin_url('admin.php?page=ezevo-integrations&integration='.$r['id'])); ?>">Edit</a><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('ezevo_test_integration');?><input type="hidden" name="action" value="ezevo_test_integration"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><button>Test</button></form><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('ezevo_activate_provider');?><input type="hidden" name="action" value="ezevo_activate_provider"><input type="hidden" name="provider" value="integration_<?php echo (int)$r['id']; ?>"><button>Activate</button></form></div></div><?php endforeach;?></div><div class="ezevo-callout"><strong>Security:</strong> secrets are encrypted at rest using WordPress salts. For high-security production, define credentials through server environment variables or a dedicated secret manager and adapt the provider class accordingly.</div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('ezevo_activate_provider');?><input type="hidden" name="action" value="ezevo_activate_provider"><input type="hidden" name="provider" value="manual"><button class="ezevo-button">Switch back to Manual Provider</button></form></section></div><?php self::footer(); }
    public static function logs(): void { global $wpdb;$rows=$wpdb->get_results("SELECT l.*,i.name integration_name FROM ".EZEV_Operations_DB::table('sync_logs')." l LEFT JOIN ".EZEV_Operations_DB::table('integrations')." i ON i.id=l.integration_id ORDER BY l.created_at DESC LIMIT 500",ARRAY_A)?:[];self::header('Sync Logs','Connection tests, webhook events and provider synchronization history.');?> <section class="ezevo-panel"><div class="ezevo-table-scroll"><table class="ezevo-table"><thead><tr><th>Time</th><th>Level</th><th>Event</th><th>Integration</th><th>Message</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo esc_html($r['created_at']); ?></td><td><span class="ezevo-pill <?php echo esc_attr($r['level']); ?>"><?php echo esc_html($r['level']); ?></span></td><td><?php echo esc_html($r['event']); ?></td><td><?php echo esc_html($r['integration_name']?:'System'); ?></td><td><?php echo esc_html($r['message']); ?></td></tr><?php endforeach;?></tbody></table></div></section><?php self::footer(); }
    public static function save_manual(): void {
        if(!current_user_can('ezev_view_operations')&&!current_user_can('manage_options'))wp_die('Denied');check_admin_referer('ezevo_save_manual');global $wpdb;$station_id=sanitize_text_field(wp_unslash($_POST['station_id']??''));$now=current_time('mysql',true);
        foreach((array)($_POST['chargers']??[]) as $id=>$data){$status=sanitize_key($data['status']??'available');$power=(float)($data['current_power_kw']??0);$wpdb->update(EZEV_Operations_DB::table('chargers'),['status'=>$status,'current_power_kw'=>$power,'provider'=>'manual','last_seen'=>$now,'updated_at'=>$now],['id'=>absint($id),'station_id'=>$station_id]);}
        $energy=(float)($_POST['energy_kwh']??0);$peak=(float)($_POST['peak_kw']??0);if($energy>0||$peak>0){$wpdb->insert(EZEV_Operations_DB::table('energy'),['station_id'=>$station_id,'recorded_at'=>$now,'grid_kwh'=>$energy*1.08,'ev_kwh'=>$energy,'solar_kwh'=>0,'bess_charge_kwh'=>0,'bess_discharge_kwh'=>0,'peak_kw'=>$peak,'provider'=>'manual']);}
        EZEV_Operations_DB::log('manual_data_updated','Manual operations data updated for '.$station_id);wp_safe_redirect(admin_url('admin.php?page=ezevo-manual&station_id='.rawurlencode($station_id).'&ezevo_notice=saved'));exit;
    }
    public static function create_ticket(): void { if(!current_user_can('ezev_view_operations'))wp_die('Denied');check_admin_referer('ezevo_create_ticket');global $wpdb;$now=current_time('mysql',true);$ticket='M-'.gmdate('YmdHis').'-'.wp_rand(100,999);$wpdb->insert(EZEV_Operations_DB::table('maintenance'),['ticket_id'=>$ticket,'station_id'=>sanitize_text_field(wp_unslash($_POST['station_id']??'')),'charger_id'=>sanitize_text_field(wp_unslash($_POST['charger_id']??'')),'priority'=>sanitize_key($_POST['priority']??'medium'),'status'=>'open','assigned_user_id'=>absint($_POST['assigned_user_id']??0)?:null,'summary'=>sanitize_text_field(wp_unslash($_POST['summary']??'')),'details'=>sanitize_textarea_field(wp_unslash($_POST['details']??'')),'opened_at'=>$now,'updated_at'=>$now]);EZEV_Operations_DB::log('maintenance_created','Created '.$ticket);wp_safe_redirect(admin_url('admin.php?page=ezevo-maintenance&ezevo_notice=saved'));exit; }
    public static function alert_action(): void { if(!current_user_can('ezev_view_operations'))wp_die('Denied');check_admin_referer('ezevo_alert_action');global $wpdb;$id=absint($_POST['id']??0);$do=sanitize_key($_POST['do']??'');$data=[];if($do==='ack')$data=['status'=>'acknowledged','acknowledged_at'=>current_time('mysql',true)];elseif($do==='resolve')$data=['status'=>'resolved','resolved_at'=>current_time('mysql',true)];if($data)$wpdb->update(EZEV_Operations_DB::table('alerts'),$data,['id'=>$id]);wp_safe_redirect(admin_url('admin.php?page=ezevo-alerts&ezevo_notice=saved'));exit; }
    public static function save_integration(): void { if(!current_user_can('manage_options'))wp_die('Denied');check_admin_referer('ezevo_save_integration');global $wpdb;$id=absint($_POST['id']??0);$old=$id?EZEV_Operations_Provider_Manager::integration($id):null;$settings=['health_endpoint'=>sanitize_text_field(wp_unslash($_POST['health_endpoint']??'')),'chargers_endpoint'=>sanitize_text_field(wp_unslash($_POST['chargers_endpoint']??'chargers')),'sessions_endpoint'=>sanitize_text_field(wp_unslash($_POST['sessions_endpoint']??'sessions')),'energy_endpoint'=>sanitize_text_field(wp_unslash($_POST['energy_endpoint']??'energy')),'alerts_endpoint'=>sanitize_text_field(wp_unslash($_POST['alerts_endpoint']??'alerts')),'timeout'=>max(3,absint($_POST['timeout']??15))];$now=current_time('mysql',true);$data=['name'=>sanitize_text_field(wp_unslash($_POST['name']??'')),'provider_type'=>sanitize_key($_POST['provider_type']??'generic_http'),'environment'=>sanitize_key($_POST['environment']??'sandbox'),'base_url'=>esc_url_raw(wp_unslash($_POST['base_url']??'')),'auth_type'=>sanitize_key($_POST['auth_type']??'bearer'),'client_id'=>sanitize_text_field(wp_unslash($_POST['client_id']??'')),'mapping_json'=>sanitize_textarea_field(wp_unslash($_POST['mapping_json']??'')),'settings_json'=>wp_json_encode($settings),'enabled'=>1,'updated_at'=>$now];foreach(['api_key','api_secret','client_secret','webhook_secret'] as $f){$col=$f.'_enc';if(!empty($_POST[$f]))$data[$col]=EZEV_Operations_Secrets::encrypt(sanitize_text_field(wp_unslash($_POST[$f])));elseif($old)$data[$col]=$old[$col]??'';}if($id){$wpdb->update(EZEV_Operations_DB::table('integrations'),$data,['id'=>$id]);}else{$data['created_at']=$now;$wpdb->insert(EZEV_Operations_DB::table('integrations'),$data);$id=(int)$wpdb->insert_id;}EZEV_Operations_DB::log('integration_saved','Saved integration '.$data['name'],'info',$id);wp_safe_redirect(admin_url('admin.php?page=ezevo-integrations&integration='.$id.'&ezevo_notice=saved'));exit; }
    public static function test_integration(): void { if(!current_user_can('manage_options'))wp_die('Denied');check_admin_referer('ezevo_test_integration');global $wpdb;$id=absint($_POST['id']??0);$r=EZEV_Operations_Provider_Manager::integration($id);if(!$r)wp_die('Integration not found');$provider=new EZEV_Operations_HTTP_Provider($r);$test=$provider->test_connection();$wpdb->update(EZEV_Operations_DB::table('integrations'),['last_test_status'=>$test['ok']?'success':'failed','last_test_message'=>sanitize_textarea_field($test['message']??''),'last_test_at'=>current_time('mysql',true)],['id'=>$id]);EZEV_Operations_DB::log('connection_test',$test['message']??'',$test['ok']?'info':'error',$id);wp_safe_redirect(admin_url('admin.php?page=ezevo-integrations&ezevo_notice='.($test['ok']?'connected':'failed')));exit; }
    public static function activate_provider(): void { if(!current_user_can('manage_options'))wp_die('Denied');check_admin_referer('ezevo_activate_provider');$p=sanitize_text_field(wp_unslash($_POST['provider']??'manual'));update_option('ezevo_active_provider',$p,false);EZEV_Operations_DB::log('provider_activated','Activated provider '.$p);wp_safe_redirect(admin_url('admin.php?page=ezevo-integrations&ezevo_notice=activated'));exit; }
    public static function run_sync(): void { if(!current_user_can('manage_options')&&!current_user_can('ezev_view_operations'))wp_die('Denied');check_admin_referer('ezevo_run_sync');$r=EZEV_Operations_Sync::run();wp_safe_redirect(admin_url('admin.php?page=ezev-operations&ezevo_notice='.($r['ok']?'synced':'failed')));exit; }
    public static function seed_demo(): void { if(!current_user_can('manage_options'))wp_die('Denied');check_admin_referer('ezevo_seed_demo');EZEV_Operations_DB::seed_demo();wp_safe_redirect(admin_url('admin.php?page=ezev-operations&ezevo_notice=seeded'));exit; }
    public static function notices(): void { if(empty($_GET['ezevo_notice']))return;$n=sanitize_key(wp_unslash($_GET['ezevo_notice']));$m=['saved'=>'Saved successfully.','connected'=>'API connection test succeeded.','failed'=>'Operation failed. Check Sync Logs for details.','activated'=>'Provider activated.','synced'=>'Synchronization completed.','seeded'=>'Demo operations data seeded.'];if(!isset($m[$n]))return;echo '<div class="notice notice-'.($n==='failed'?'error':'success').' is-dismissible"><p>'.esc_html($m[$n]).'</p></div>'; }
}
